.pm-chapter-section { --ink: #2D3748; --muted: #718096; --accent: #2C5282; --warm: #DD6B20; --line: #E2E8F0; --paper: #F7FAFC; font-family: system-ui, -apple-system, sans-serif; color: var(--ink); background: var(--paper); padding: 24px; margin-bottom: 32px; border-radius: 8px; border: 1px solid var(--line); }
.pm-section-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; border-bottom: 2px solid var(--accent); padding-bottom: 10px; }
.pm-title { font-size: 24px; margin: 0; color: var(--accent); }
.pm-source-btn { background: transparent; border: 1px solid var(--muted); color: var(--muted); padding: 4px 12px; border-radius: 4px; font-size: 13px; cursor: pointer; }
.pm-source-btn:hover { border-color: var(--accent); color: var(--accent); }
.pm-content-grid { display: grid; grid-template-columns: 1fr 380px; gap: 32px; }
@media (max-width: 768px) { .pm-content-grid { grid-template-columns: 1fr; } }
.pm-text-flow { font-size: 16px; line-height: 1.6; }
.pm-lead { font-size: 18px; color: var(--ink); margin-bottom: 16px; }
.pm-formula-block { background: #fff; border: 1px solid var(--line); padding: 16px; margin: 16px 0; border-radius: 6px; text-align: center; }
.pm-formula { font-family: 'Times New Roman', serif; font-size: 18px; color: var(--accent); }
.pm-formula-note { font-size: 12px; color: var(--muted); margin-top: 8px; }
.pm-lab-panel { background: #fff; border: 1px solid var(--line); padding: 20px; border-radius: 8px; }
.pm-lab-title { font-size: 18px; margin: 0 0 16px 0; color: var(--accent); }
.pm-control-group { margin-bottom: 16px; }
.pm-control-label { display: block; font-size: 14px; font-weight: 600; margin-bottom: 8px; color: var(--ink); }
.pm-input-row { display: flex; gap: 8px; }
.pm-input-row input { width: 100%; padding: 6px; border: 1px solid var(--line); border-radius: 4px; font-size: 14px; }
.pm-matrix-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; }
.pm-matrix-grid input { width: 100%; padding: 4px; border: 1px solid var(--line); border-radius: 4px; font-size: 13px; text-align: center; }
.pm-checkbox-label { display: flex; align-items: center; gap: 8px; font-size: 14px; color: var(--warm); cursor: pointer; }
.pm-lab-output { margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--line); }
.pm-output-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
.pm-label { font-size: 14px; font-weight: 600; }
.pm-bars-container { display: flex; align-items: flex-end; gap: 4px; height: 140px; width: 100%; border-bottom: 1px solid var(--ink); padding-bottom: 2px; }
.pm-bar { flex: 1; background: var(--accent); opacity: 0.8; border-radius: 2px 2px 0 0; position: relative; transition: height 0.3s; min-height: 2px; }
.pm-bar-val { position: absolute; top: -20px; left: 50%; transform: translateX(-50%); font-size: 11px; color: var(--ink); }
.pm-value-display { font-family: monospace; font-size: 16px; color: var(--accent); font-weight: bold; }
.pm-btn-reset { width: 100%; padding: 10px; background: var(--muted); color: #fff; border: none; border-radius: 4px; font-size: 14px; cursor: pointer; margin-top: 16px; }
.pm-btn-reset:hover { background: var(--accent); }
.pm-head-visual { display: flex; flex-direction: column; gap: 12px; }
.pm-head-block { border: 1px solid var(--line); padding: 12px; border-radius: 6px; background: #fff; }
.pm-head-label { font-size: 13px; font-weight: bold; color: var(--muted); display: block; margin-bottom: 4px; }
.pm-projection { font-family: monospace; font-size: 12px; color: var(--accent); }
.pm-subspace-val { font-size: 13px; color: var(--ink); margin-top: 4px; }
.pm-concat { border-color: var(--accent); background: #F0F4F8; }
.pm-limitation-note { font-size: 12px; color: var(--muted); margin-top: 12px; font-style: italic; }
.head-weight-row{display:grid;grid-template-columns:55px minmax(0,1fr) 50px;gap:12px;align-items:center;margin:12px 0;font-size:14px}.head-track,.head-bar{height:18px}.head-track{background:#edf0ed}.head-bar{background:#ad472d}#head-select{margin:14px 0;max-width:100%}

.pm-content-grid{grid-template-columns:minmax(0,1fr)}.pm-text-flow{line-height:1.9}.pm-lab-panel{display:block;padding:24px;background:#fff}.pm-input-row input[type=range]{min-width:0;flex:1;width:0}.pm-input-row{align-items:center}.pm-bars-container{margin-top:28px}.attn-calculation{font-size:14px;line-height:1.9;font-variant-numeric:tabular-nums;padding-top:12px;border-top:1px solid var(--line)}.attn-calculation p{margin:8px 0}.pm-bar{min-height:0}.pm-bar-val{font-size:12px}.pm-output-row{gap:16px}.pm-input-row input,.pm-matrix-grid input{min-width:0}.pm-head-visual{display:block}

section[id]{--ink:#233342;--muted:#596877;--accent:#265976;--warm:#ad472d;--line:#d6dcd9;--paper:#fcfbf8;background:transparent;border:0;border-radius:0;padding:0;max-width:100%;color:var(--ink)}
section[id] h2{color:#233342;font-family:Georgia,"Noto Serif SC",SimSun,serif;font-weight:500;font-size:29px;line-height:1.5}
section[id]>header{border-bottom:1px solid #d6dcd9}section[id] p{line-height:1.9}
section[id] [class*="formula"]{max-width:100%;overflow-x:auto}
section[id] [class*="panel"],section[id] [class*="workbench"]{box-shadow:none}
@media(max-width:600px){section[id] div{min-width:0;max-width:100%}section[id] h2{font-size:25px}section[id] [class*="grid"]{grid-template-columns:minmax(0,1fr)}section[id] .pm-matrix-grid{grid-template-columns:repeat(3,minmax(0,1fr))}section[id] .pm-input-row input{min-width:0;flex:1;width:0}section[id] .pm-control-group{flex-wrap:wrap}section[id] .pm-control-group label{min-width:0;flex-basis:100%}section[id] .pm-section-header{flex-wrap:wrap}section[id] .pm-lab-panel,section[id] .interaction-panel{padding:14px}section[id] .pm-head-visual{display:block}section[id] .pm-control-group span{min-width:0}}

