(function() {
  const getVal = (id) => parseFloat(document.getElementById(id).value) || 0;
  const setVal = (id, val) => { const el = document.getElementById(id); if(el) el.value = val; };
  const setChecked = (id, val) => { const el = document.getElementById(id); if(el) el.checked = val; };

  const softmax = (arr) => {
    const max = Math.max(...arr);
    const exps = arr.map(x => Math.exp(x - max));
    const sum = exps.reduce((a, b) => a + b, 0);
    return exps.map(x => x / sum);
  };

  const calculateAttention = () => {
    const q = [getVal('attn-q-0'), getVal('attn-q-1'), getVal('attn-q-2')];
    const k = [
      [getVal('attn-k-0-0'), getVal('attn-k-0-1'), getVal('attn-k-0-2')],
      [getVal('attn-k-1-0'), getVal('attn-k-1-1'), getVal('attn-k-1-2')],
      [getVal('attn-k-2-0'), getVal('attn-k-2-1'), getVal('attn-k-2-2')]
    ];
    const v = [getVal('attn-v-0'), getVal('attn-v-1'), getVal('attn-v-2')];
    const mask = document.getElementById('attn-mask').checked;

    // Dot product Q * K^T (Q is 1x3, K is 3x3, result 1x3 scores for 3 keys)
    // K rows are keys. Q dot Key_i
    const scores = k.map(key => {
      let sum = 0;
      for(let i=0; i<3; i++) sum += q[i] * key[i];
      return sum;
    });

    // Scale by sqrt(3)
    const scale = Math.sqrt(3);
    const scaled = scores.map(s => s / scale);

    // Mask
    if (mask) {
      scaled[2] = -1e9; // Mask key index 2
    }

    // Softmax
    const weights = softmax(scaled);

    // Output = weights dot V
    let output = 0;
    for(let i=0; i<3; i++) output += weights[i] * v[i];

    const calculation=document.getElementById('attn-calculation');if(calculation){calculation.replaceChildren();
      for(const [label,values] of [['Q · K',scores],['除以 √3',scores.map(s=>s/scale)],['Softmax 权重',weights]]){const p=document.createElement('p');p.textContent=label+' → ['+values.map(v=>v.toFixed(3)).join(', ')+']';calculation.append(p);}
      const p=document.createElement('p');p.textContent='Q = ['+q.join(', ')+']；输出 = Σ(权重 × V) = '+output.toFixed(4);calculation.append(p);
    }
    updateHeads(q,k,v);
    // Update Visuals
    const weightsEl = document.getElementById('attn-weights');
    if(weightsEl) {
      weightsEl.setAttribute('data-values', JSON.stringify(weights.map(w => parseFloat(w.toFixed(4)))));
      const bars = weightsEl.querySelectorAll('.pm-bar');
      bars.forEach((bar, idx) => {
        const h = weights[idx] * 140; // min 2px for visibility
        bar.style.height = h + 'px';
        const valSpan = bar.querySelector('.pm-bar-val');
        if(valSpan) valSpan.textContent = weights[idx].toFixed(2);
      });
    }

    const outputEl = document.getElementById('attn-output');
    if(outputEl) {
      outputEl.setAttribute('data-value', parseFloat(output.toFixed(4)));
      outputEl.textContent = output.toFixed(2);
    }
  };

  function updateHeads(q,k,v){
    const results=[0,2].map(index=>{const scores=k.map(key=>q[index]*key[index]);if(document.getElementById('attn-mask').checked)scores[2]=-1e9;const w=softmax(scores);return {w,out:w.reduce((s,value,i)=>s+value*v[i],0)};});
    const select=document.getElementById('head-select'),plot=document.getElementById('head-weights');if(!plot)return;
    const chosen=results[Number(select.value)||0];plot.dataset.values=JSON.stringify(chosen.w);plot.replaceChildren();
    chosen.w.forEach((w,i)=>{const row=document.createElement('div');row.className='head-weight-row';const label=document.createElement('span');label.textContent='位置 '+(i+1);const track=document.createElement('div');track.className='head-track';const bar=document.createElement('div');bar.className='head-bar';bar.style.width=w*100+'%';track.append(bar);const value=document.createElement('output');value.textContent=w.toFixed(3);row.append(label,track,value);plot.append(row);});
    document.getElementById('head-concat').textContent='拼接输出 ['+results.map(r=>r.out.toFixed(3)).join(', ')+']';
    const output=results.reduce((s,r)=>s+r.out,0)/2;const el=document.getElementById('head-output');el.dataset.value=output;el.textContent='经 Wᴼ 投影后的示例输出：'+output.toFixed(4);
  }
  document.getElementById('head-select').addEventListener('change',calculateAttention);
  const resetAttention = () => {
    setVal('attn-q-0', 1); setVal('attn-q-1', 0); setVal('attn-q-2', 2);
    setVal('attn-k-0-0', 1); setVal('attn-k-0-1', 0); setVal('attn-k-0-2', 1);
    setVal('attn-k-1-0', 0); setVal('attn-k-1-1', 1); setVal('attn-k-1-2', -1);
    setVal('attn-k-2-0', -1); setVal('attn-k-2-1', 1); setVal('attn-k-2-2', 0);
    setVal('attn-v-0', 1); setVal('attn-v-1', 2); setVal('attn-v-2', -1);
    setChecked('attn-mask', false);
    calculateAttention();
  };

  const init = () => {
    const inputs = document.querySelectorAll('#attention-lab input');
    inputs.forEach(input => {
      input.addEventListener('input', calculateAttention);
      input.addEventListener('change', calculateAttention);
    });
    const resetBtn = document.getElementById('attn-reset');
    if(resetBtn) resetBtn.addEventListener('click', resetAttention);

    // Initial calc
    calculateAttention();
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
